ga4c(){return"\u0646\u0627\u0631\u062f\u0646\u06cc \u0628\u06d5\u0633\u062a\u06d5\u0631\u06cc \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5"},
ga4d(){return"\u0626\u06d5\u06af\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9 \u0628\u06c6 \u0626\u06d5\u0648 \u0626\u06cc\u0645\u06d5\u06cc\u06b5\u06d5 \u0647\u06d5\u0628\u06ce\u062a\u060c \u0628\u06d5\u0633\u062a\u06d5\u0631\u06cc \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06d5\u0645 \u0632\u0648\u0648\u0627\u0646\u06d5 \u062f\u06d5\u06af\u0627\u062a\u06ce."},
ga4b(){return"\u0626\u06cc\u0645\u06d5\u06cc\u06b5\u06d5\u06a9\u06d5\u062a \u0628\u0646\u0648\u0648\u0633\u06d5"},
gac4(){return"\u062f\u0627\u0646\u0627\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
gac2(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06d5\u06a9\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5."},
gac0(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
gabZ(){return"\u062f\u0648\u0648\u067e\u0627\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
gac1(){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gac3(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5. \u062a\u06a9\u0627\u06cc\u06d5 \u0628\u06d5 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0628\u0686\u06c6\u0631\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5."},
gacz(){return"\u0686\u06d5\u0646\u0627\u06af\u06d5\u06cc \u062a\u06d5\u0648\u0627\u0648 / \u0646\u06cc\u06cc\u06d5"},
