gOF(){return"\u062a\u06d5\u0648\u0627\u0648\u0628\u0648\u0648"},
gOI(){return"\u0646\u06cc\u0634\u0627\u0646\u06a9\u0631\u062f\u0646 \u0648\u06d5\u06a9 \u062a\u06d5\u0648\u0627\u0648\u0628\u0648\u0648"},
