gOv(){return"\u0626\u06d5\u06a4\u06ce \u06a9\u0627\u0644\u0627\u06cc\u06ce \u0631\u06d5\u0646\u06af/\u0642\u06d5\u0628\u0627\u0631\u06ce\u0646 \u062e\u06c6 \u0647\u06d5\u0646\u06d5\u060c \u0644\u06d5\u0648\u0645\u0627 \u0648\u06d5\u06a9 \u0645\u0627\u062f\u062f\u0627 \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u062f\u0645\u06cc\u0646\u06cc\u062a"},
gOt(){return"\u0628\u0627\u0631\u06a9\u06c6\u062f\u06ce \u0642\u0648\u062a\u06cc\u06ce (\u0698\u0645\u0627\u0631\u0627 \u0628\u06d5\u0631\u0647\u06d5\u0645\u06cc)"},
